const triggerJson = $input.first().json;
const texto = (triggerJson.callback_query?.data || triggerJson.message?.text || '').trim();

const NOMBRES_MESES = [
  null,
  'ENERO', 'FEBRERO', 'MARZO', 'ABRIL', 'MAYO', 'JUNIO',
  'JULIO', 'AGOSTO', 'SEPTIEMBRE', 'OCTUBRE', 'NOVIEMBRE', 'DICIEMBRE'
];

const match = texto.match(/^\/mes_(1[0-2]|[1-9])(@.*)?$/);

if (!match) {
  throw new Error('Comando no reconocido. Usa /mes_1 (Enero) hasta /mes_12 (Diciembre).');
}

const mesNumero = parseInt(match[1], 10);
const mesNombre = NOMBRES_MESES[mesNumero];

return [{
  json: {
    ...$json,
    comandoValido: true,
    mesNombre: mesNombre,
    mesNumero: mesNumero,
    executionType: 'visual_report'
  }
}];

const inputItems = $input.all();

const NOMBRES_MESES = [
  'ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO',
  'JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE'
];

let mesNombre = null;
try {
  const nodoMes = $('Extraer Mes del Mensaje');
  if (nodoMes && nodoMes.first()) {
    mesNombre = nodoMes.first().json.mesNombre;
  }
} catch (e) {}

if (!mesNombre) {
  const hoy = new Date();
  mesNombre = NOMBRES_MESES[hoy.getMonth()];
}

// =========================================================
// BLINDAJE ANTI-BALAS: nunca se detiene el flujo con un throw.
// Si algo falla, se devuelve un item con "archivoNoEncontrado:true"
// y un mensaje claro que el nodo "¿Archivo Encontrado?" enruta
// directo a Telegram, en vez de que n8n marque la ejecución en rojo.
// =========================================================
if (!inputItems || inputItems.length === 0) {
  return [{
    json: {
      archivoNoEncontrado: true,
      mesNombre: mesNombre,
      message: '⚠️ <b>ROYAL EXPRESS C.A.</b>\n\nNo se encontraron archivos en la carpeta de OneDrive.\nVerifica que la carpeta "2026" exista y contenga los informes mensuales.'
    }
  }];
}

let listaArchivos = [];
const primerJson = inputItems[0].json;

if (primerJson && Array.isArray(primerJson.value)) {
  listaArchivos = primerJson.value;
} else {
  listaArchivos = inputItems.map(it => it.json).filter(Boolean);
}

if (listaArchivos.length === 0) {
  return [{
    json: {
      archivoNoEncontrado: true,
      mesNombre: mesNombre,
      message: '⚠️ <b>ROYAL EXPRESS C.A.</b>\n\nLa carpeta "2026" no devolvió archivos. Verifica los permisos de OneDrive o que existan los .xlsx mensuales.'
    }
  }];
}

const archivoEncontrado = listaArchivos.find(archivo => {
  const nombre = (archivo && archivo.name) ? archivo.name.toUpperCase() : '';
  if (!nombre) return false;
  return nombre.endsWith('.XLSX') && nombre.includes(mesNombre);
});

if (!archivoEncontrado) {
  const nombresDisponibles = listaArchivos.map(a => a && a.name).filter(Boolean).join(', ') || 'ninguno';
  return [{
    json: {
      archivoNoEncontrado: true,
      mesNombre: mesNombre,
      message: '⚠️ <b>ROYAL EXPRESS C.A.</b>\n\nNo se encontró el archivo .xlsx de <b>' + mesNombre + '</b> en la carpeta "2026".\n\nArchivos disponibles:\n' + nombresDisponibles
    }
  }];
}

return [{ json: { ...archivoEncontrado, mesNombre, archivoNoEncontrado: false } }];

let executionType = 'daily_report';
let semanaNumero = null;

try {
  const trigger = $('Telegram Trigger').first();
  if (trigger && trigger.json) {
    const txt = (trigger.json.callback_query?.data || trigger.json.message?.text || '').trim();
    if (/^\/anual(@.*)?$/.test(txt)) {
      executionType = 'annual_report';
    } else if (/^\/graficas_mes_actual(@.*)?$/.test(txt) || /^\/mes_(1[0-2]|[1-9])(@.*)?$/.test(txt)) {
      executionType = 'visual_report';
    } else if (/^\/semana\s*([1-5])(@.*)?$/.test(txt)) {
      executionType = 'weekly_report';
      const m = txt.match(/\d+/);
      semanaNumero = m ? parseInt(m[0], 10) : null;
    } else if (/^\/reporte(@.*)?$/.test(txt)) {
      executionType = 'daily_report';
    }
  }
} catch (e) {}

try {
  const n = $('Modo Alerta 2H').first();
  if (n && n.json && n.json.executionType === 'alert_check') {
    executionType = 'alert_check';
  }
} catch (e) {}

try {
  const n = $('Modo Reporte Semanal').first();
  if (n && n.json && n.json.executionType === 'weekly_report') {
    executionType = 'weekly_report';
    semanaNumero = parseInt(n.json.semanaNumero, 10) || null;
  }
} catch (e) {}

try {
  const n = $('Modo Reporte Visual').first();
  if (n && n.json && n.json.executionType === 'visual_report') {
    executionType = 'visual_report';
  }
} catch (e) {}

try {
  const n = $('Modo Reporte Anual').first();
  if (n && n.json && n.json.executionType === 'annual_report') {
    executionType = 'annual_report';
  }
} catch (e) {}

return $input.all().map(item => ({
  json: {
    ...item.json,
    executionType: executionType,
    semanaNumero: semanaNumero
  }
}));

// =========================================================
// ROYAL EXPRESS C.A. - CALCULAR DATOS REPORTE VISUAL (MES Y SEMANA)
// =========================================================
const PRESUPUESTO_MENSUAL_GLOBAL = 27000.00;

const DEPARTAMENTOS_CONFIG = [
  { codigo: 'GO',  nombre: 'Operaciones',            limiteMensual: 500.00,   emoji: '📊' },
  { codigo: 'GC1', nombre: 'Combustible Gasoil',      limiteMensual: 2000.00,  emoji: '⛽' },
  { codigo: 'GC2', nombre: 'Combustible Gasolina',    limiteMensual: 800.00,   emoji: '⛽' },
  { codigo: 'GA',  nombre: 'Administrativos',         limiteMensual: 1000.00,  emoji: '🧾' },
  { codigo: 'GM',  nombre: 'Mantenimiento',           limiteMensual: 6000.00,  emoji: '⚙️' },
  { codigo: 'GR',  nombre: 'Representativos',         limiteMensual: 100.00,   emoji: '🤝' },
  { codigo: 'GL',  nombre: 'Lubricantes',             limiteMensual: 500.00,   emoji: '🛢️' },
  { codigo: 'GS',  nombre: 'Seguridad',               limiteMensual: 100.00,   emoji: '⛑️' },
  { codigo: 'GN',  nombre: 'Nomina',                  limiteMensual: 16000.00, emoji: '👥' },
  { codigo: 'GMD', nombre: 'Gastos Medicos',          limiteMensual: 200.00,   emoji: '🩺' }
];

const COLORES_CATEGORIA = {
  GO:  '#38bdf8', GC1: '#f59e0b', GC2: '#fbbf24', GA:  '#a78bfa',
  GM:  '#f87171', GR:  '#34d399', GL:  '#22d3ee', GS:  '#fb7185', GN:  '#ec4899',
  GMD: '#10b981'
};

const inputItems = $input.all();

function obtenerCampo(row, aliasList) {
  if (!row || typeof row !== 'object') return undefined;
  const keys = Object.keys(row);
  for (const key of keys) {
    const keyLimpia = key.trim().toUpperCase();
    for (const alias of aliasList) {
      if (keyLimpia === alias.toUpperCase()) {
        const val = row[key];
        if (val !== undefined && val !== null && val !== '') return val;
      }
    }
  }
  for (const key of keys) {
    const keyLimpia = key.trim().toUpperCase();
    for (const alias of aliasList) {
      if (alias.length > 2 && keyLimpia.includes(alias.toUpperCase())) {
        const val = row[key];
        if (val !== undefined && val !== null && val !== '') return val;
      }
    }
  }
  return undefined;
}

function detectarMapaColumnas(items) {
  const objetivos = {
    FECHA: ['FECHA', 'FECHA GASTO', 'FECHA DE GASTO'],
    TIPO: ['TIPO DE GASTO', 'TIPO GASTO'],
    MONTO: ['$']
  };
  for (const item of items) {
    const row = item.json || {};
    const keys = Object.keys(row);
    const mapaTemp = {};
    for (const key of keys) {
      const val = row[key];
      if (val === undefined || val === null || val === '') continue;
      const valLimpio = String(val).trim().toUpperCase();
      for (const campo of Object.keys(objetivos)) {
        if (mapaTemp[campo]) continue;
        if (objetivos[campo].indexOf(valLimpio) !== -1) {
          mapaTemp[campo] = key;
        }
      }
    }
    if (mapaTemp.FECHA && mapaTemp.TIPO && mapaTemp.MONTO) {
      return mapaTemp;
    }
  }
  return null;
}

function leerCampo(row, mapaColumnas, campo, aliasEstatico) {
  if (mapaColumnas && mapaColumnas[campo]) {
    const val = row[mapaColumnas[campo]];
    if (val !== undefined && val !== null && val !== '') return val;
  }
  return obtenerCampo(row, aliasEstatico);
}

function extraerMonto(valor) {
  if (valor === undefined || valor === null || valor === '') return 0;
  if (typeof valor === 'number') return isNaN(valor) ? 0 : valor;
  let str = String(valor).trim();
  if (!str) return 0;
  let esNegativo = false;
  if (str.startsWith('(') && str.endsWith(')')) {
    esNegativo = true;
    str = str.slice(1, -1);
  }
  str = str.replace(/[^0-9.,-]/g, '');
  if (!str) return 0;
  const lastDot = str.lastIndexOf('.');
  const lastComma = str.lastIndexOf(',');
  if (lastDot !== -1 && lastComma !== -1) {
    if (lastComma > lastDot) {
      str = str.replace(/\./g, '').replace(',', '.');
    } else {
      str = str.replace(/,/g, '');
    }
  } else if (lastComma !== -1) {
    str = str.replace(',', '.');
  }
  let num = parseFloat(str);
  if (isNaN(num)) return 0;
  return esNegativo ? -num : num;
}

function parseFecha(valor) {
  if (!valor) return null;
  if (valor instanceof Date) return isNaN(valor.getTime()) ? null : valor;
  if (typeof valor === 'number') {
    if (valor > 30000 && valor < 60000) {
      const dateMs = (valor - 25569) * 86400 * 1000;
      const temp = new Date(dateMs);
      return new Date(temp.getUTCFullYear(), temp.getUTCMonth(), temp.getUTCDate());
    }
    return null;
  }
  const str = String(valor).trim();
  if (!str) return null;
  const matchDMY = str.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})/);
  if (matchDMY) {
    let day = parseInt(matchDMY[1], 10);
    let month = parseInt(matchDMY[2], 10) - 1;
    let year = parseInt(matchDMY[3], 10);
    if (year < 100) year += 2000;
    if (day > 31 && year <= 31) return new Date(day, month, year);
    return new Date(year, month, day);
  }
  const parsed = new Date(str);
  return isNaN(parsed.getTime()) ? null : parsed;
}

function normalizarCodigo(texto) {
  if (!texto) return null;
  const str = String(texto).trim().toUpperCase();
  if (str === 'G1') return 'GC1';
  if (str === 'G2') return 'GC2';
  const codigosOficiales = DEPARTAMENTOS_CONFIG.map(d => d.codigo);
  if (codigosOficiales.includes(str)) return str;
  return null;
}

function getDiasDelMes(year, month) {
  return new Date(year, month, 0).getDate();
}

function generarSemanasDelMes(year, month) {
  const diasTotales = getDiasDelMes(year, month);
  const definiciones = [
    { inicio: 1, fin: 9 },
    { inicio: 10, fin: 16 },
    { inicio: 17, fin: 23 },
    { inicio: 24, fin: diasTotales }
  ];
  return definiciones.map(def => ({
    inicio: new Date(year, month - 1, def.inicio, 0, 0, 0, 0),
    fin: new Date(year, month - 1, Math.min(def.fin, diasTotales), 23, 59, 59, 999)
  }));
}

const ALIAS_FECHA = ['FECHA', 'FECHA GASTO', 'FECHA DE GASTO', 'DIA', 'DÍA', '__EMPTY_1', 'B'];
const ALIAS_TIPO  = ['TIPO DE GASTO', 'TIPO GASTO', 'CODIGO', 'CÓDIGO', 'DEPTO', 'DEPARTAMENTO', 'TIPO', '__EMPTY_6', '__EMPTY_3', 'G'];
const ALIAS_MONTO = ['$', 'MONTO', 'MONTO ($)', 'IMPORTE', 'GASTO', 'VALOR', 'TOTAL', '__EMPTY_9', '__EMPTY_6', 'J'];

const mapaColumnas = detectarMapaColumnas(inputItems);

let mesExcel = null, anioExcel = null;
for (const item of inputItems) {
  const row = item.json || {};
  const fechaRaw = leerCampo(row, mapaColumnas, 'FECHA', ALIAS_FECHA);
  if (fechaRaw) {
    const fecha = parseFecha(fechaRaw);
    if (fecha && !isNaN(fecha.getTime())) {
      mesExcel = fecha.getMonth() + 1;
      anioExcel = fecha.getFullYear();
      break;
    }
  }
}
if (!mesExcel || !anioExcel) {
  const hoy = new Date();
  mesExcel = hoy.getMonth() + 1;
  anioExcel = hoy.getFullYear();
}

const NOMBRES_MESES = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
const nombreMes = NOMBRES_MESES[mesExcel - 1];
const diasTotalesMes = getDiasDelMes(anioExcel, mesExcel);
const semanasDelMes = generarSemanasDelMes(anioExcel, mesExcel);
const numSemanas = semanasDelMes.length;

const matriz = {};
DEPARTAMENTOS_CONFIG.forEach(d => { matriz[d.codigo] = new Array(numSemanas).fill(0); });
let gastoTotalMes = 0;
let ultimaFechaConGasto = null;

for (const item of inputItems) {
  const row = item.json || {};
  const codigo = normalizarCodigo(leerCampo(row, mapaColumnas, 'TIPO', ALIAS_TIPO));
  if (!codigo) continue;
  const monto = extraerMonto(leerCampo(row, mapaColumnas, 'MONTO', ALIAS_MONTO));
  if (monto === 0) continue;
  const fechaGasto = parseFecha(leerCampo(row, mapaColumnas, 'FECHA', ALIAS_FECHA));
  if (!fechaGasto) continue;
  if ((fechaGasto.getMonth() + 1) !== mesExcel || fechaGasto.getFullYear() !== anioExcel) continue;

  if (!ultimaFechaConGasto || fechaGasto > ultimaFechaConGasto) ultimaFechaConGasto = fechaGasto;

  for (let s = 0; s < numSemanas; s++) {
    if (fechaGasto >= semanasDelMes[s].inicio && fechaGasto <= semanasDelMes[s].fin) {
      matriz[codigo][s] += monto;
      gastoTotalMes += monto;
      break;
    }
  }
}

let executionType = 'visual_report';
let semanaNumero = null;
try {
  const inputFirst = inputItems[0]?.json || {};
  if (inputFirst.executionType) executionType = inputFirst.executionType;
  if (inputFirst.semanaNumero) semanaNumero = parseInt(inputFirst.semanaNumero, 10);
} catch(e) {}

const categorias = DEPARTAMENTOS_CONFIG.map(dept => {
  const { codigo, nombre, emoji, limiteMensual } = dept;
  const porSemana = matriz[codigo].map(v => Math.round(v * 100) / 100);
  const total = porSemana.reduce((a, b) => a + b, 0);
  const pctTotal = gastoTotalMes > 0 ? (total / gastoTotalMes) * 100 : 0;
  const promedioSemanal = numSemanas > 0 ? total / numSemanas : 0;
  const semanasConGastos = porSemana.filter(v => v > 0).length;
  return {
    codigo, nombre, emoji, color: COLORES_CATEGORIA[codigo] || '#94a3b8',
    limiteMensual,
    porSemana,
    total: Math.round(total * 100) / 100,
    pctTotal: Math.round(pctTotal * 10) / 10,
    promedioSemanal: Math.round(promedioSemanal * 100) / 100,
    semanasConGastos,
    numSemanas
  };
});

const semanas = semanasDelMes.map((sem, i) => {
  let totalSemana = 0;
  const porCategoria = {};
  DEPARTAMENTOS_CONFIG.forEach(d => {
    const v = matriz[d.codigo][i];
    porCategoria[d.codigo] = Math.round(v * 100) / 100;
    totalSemana += v;
  });
  return {
    indice: i + 1,
    nombre: 'Semana ' + (i + 1),
    porCategoria: porCategoria,
    totalSemana: Math.round(totalSemana * 100) / 100,
    pctMes: gastoTotalMes > 0 ? Math.round((totalSemana / gastoTotalMes) * 1000) / 10 : 0
  };
});

const hayDatos = gastoTotalMes > 0;
const categoriasConGastos = categorias.filter(c => c.total > 0).length;

const hoy2 = new Date();
const esMesActualCalc = (mesExcel === (hoy2.getMonth() + 1)) && (anioExcel === hoy2.getFullYear());
const fechaReferencia = ultimaFechaConGasto || hoy2;

let semanaActualIdx = (semanaNumero && semanaNumero >= 1 && semanaNumero <= numSemanas) ? (semanaNumero - 1) : 0;
if (!semanaNumero) {
  for (let s = 0; s < numSemanas; s++) {
    if (fechaReferencia >= semanasDelMes[s].inicio && fechaReferencia <= semanasDelMes[s].fin) {
      semanaActualIdx = s;
      break;
    } else if (fechaReferencia > semanasDelMes[s].fin) {
      semanaActualIdx = s;
    }
  }
}
const semanaActualObj = semanasDelMes[semanaActualIdx];
const opcionesFecha = { day: '2-digit', month: '2-digit', year: 'numeric' };
const labelPeriodoSemana = semanaActualObj.inicio.toLocaleDateString('es-ES', opcionesFecha) + ' al ' + semanaActualObj.fin.toLocaleDateString('es-ES', opcionesFecha);

const diasTranscurridos = esMesActualCalc
  ? Math.min(hoy2.getDate(), diasTotalesMes)
  : diasTotalesMes;
const diasTranscurridosSeguro = diasTranscurridos > 0 ? diasTranscurridos : 1;

const categoriasConSemana = categorias.map(function(c) {
  const gastoSemana = c.porSemana[semanaActualIdx] || 0;
  const limiteSemanal = Math.round((c.limiteMensual / numSemanas) * 100) / 100;
  const disponibleSemana = Math.round((limiteSemanal - gastoSemana) * 100) / 100;
  const porcentajeMensual = c.limiteMensual > 0 ? Math.round((c.total / c.limiteMensual) * 1000) / 10 : 0;
  const proyeccionCierre = (c.total / diasTranscurridosSeguro) * diasTotalesMes;
  const porcentajeProyectado = c.limiteMensual > 0 ? Math.round((proyeccionCierre / c.limiteMensual) * 1000) / 10 : 0;
  const excesoProyectado = Math.max(0, Math.round((proyeccionCierre - c.limiteMensual) * 100) / 100);
  return Object.assign({}, c, {
    gastoSemana: Math.round(gastoSemana * 100) / 100,
    limiteSemanal: limiteSemanal,
    disponibleSemana: disponibleSemana,
    porcentajeMensual: porcentajeMensual,
    gastoMensual: c.total,
    proyeccionCierre: Math.round(proyeccionCierre * 100) / 100,
    porcentajeProyectado: porcentajeProyectado,
    excesoProyectado: excesoProyectado
  });
});

const etiquetasSemanas = semanas.map(function(s) { return s.nombre; });
const seriesEvolucion = categorias
  .filter(function(c) { return c.total > 0; })
  .map(function(c) { return { nombre: c.nombre, color: c.color, valores: c.porSemana }; });

const distribucion = categorias
  .filter(function(c) { return c.total > 0; })
  .map(function(c) {
    return {
      nombre: c.nombre, emoji: c.emoji, color: c.color,
      monto: c.total,
      porcentaje: gastoTotalMes > 0 ? Math.round((c.total / gastoTotalMes) * 1000) / 10 : 0
    };
  });

const porcentajeGlobalMensual = PRESUPUESTO_MENSUAL_GLOBAL > 0
  ? Math.round((gastoTotalMes / PRESUPUESTO_MENSUAL_GLOBAL) * 1000) / 10
  : 0;
const saldoDisponibleGlobal = Math.round((PRESUPUESTO_MENSUAL_GLOBAL - gastoTotalMes) * 100) / 100;

let chatId = null;
try { chatId = $('Telegram Trigger').first().json.message.chat.id; } catch (e) {}

const gastoSemanaConsultada = semanas[semanaActualIdx]?.totalSemana || 0;
const distribucionSemana = categorias
  .filter(function(c) { return (c.porSemana[semanaActualIdx] || 0) > 0; })
  .map(function(c) {
    const montoSem = c.porSemana[semanaActualIdx] || 0;
    return {
      nombre: c.nombre, emoji: c.emoji, color: c.color,
      monto: montoSem,
      porcentaje: gastoSemanaConsultada > 0 ? Math.round((montoSem / gastoSemanaConsultada) * 1000) / 10 : 0
    };
  });

return [{
  json: {
    chatId: chatId,
    executionType: executionType,
    semanaNumero: (semanaActualIdx + 1),
    gastoSemanaConsultada: gastoSemanaConsultada,
    distribucionSemana: distribucionSemana,
    mes: nombreMes,
    mesNumero: mesExcel,
    anio: anioExcel,
    diasTotalesMes: diasTotalesMes,
    diasTranscurridos: diasTranscurridos,
    numSemanas: numSemanas,
    gastoTotalMes: Math.round(gastoTotalMes * 100) / 100,
    gastoTotalGlobalMes: Math.round(gastoTotalMes * 100) / 100,
    promedioSemanal: Math.round((gastoTotalMes / numSemanas) * 100) / 100,
    categoriasConGastos: categoriasConGastos,
    totalCategorias: DEPARTAMENTOS_CONFIG.length,
    presupuestoGlobal: PRESUPUESTO_MENSUAL_GLOBAL,
    saldoDisponibleGlobal: saldoDisponibleGlobal,
    porcentajeGlobalMensual: porcentajeGlobalMensual,
    labelPeriodoSemana: labelPeriodoSemana,
    etiquetasSemanas: etiquetasSemanas,
    seriesEvolucion: seriesEvolucion,
    distribucion: distribucion,
    categorias: categoriasConSemana,
    semanas: semanas,
    hayDatos: hayDatos,
    fechaGeneracion: new Date().toLocaleString('es-VE', { dateStyle: 'long', timeStyle: 'short' })
  }
}];

// =========================================================
// ROYAL EXPRESS C.A. - GENERADOR DE HTML PARA GASTOS (CON FIRMA ING. VLADIMIR MARCANO)
// =========================================================

const d = $input.first().json;

if (!d.hayDatos || d.gastoTotalMes === 0) {
  const mensaje = '📋 <b>INFORME DE GASTOS - ' + d.mes.toUpperCase() + ' ' + d.anio + '</b>\n\n' +
                  '⚠️ <b>NO HAY DATOS REGISTRADOS</b>\n\n' +
                  'El archivo Excel para el mes de <b>' + d.mes + ' ' + d.anio + '</b> no contiene gastos registrados.';

  return [{
    json: {
      sendNotification: true,
      executionType: d.executionType || 'visual_report',
      message: mensaje,
      esMensajeTexto: true,
      chatId: d.chatId
    }
  }];
}

const hoy = new Date();
const mesActual = hoy.getMonth() + 1;
const anioActual = hoy.getFullYear();

const mesExcel = d.mesNumero || (function() {
  var meses = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
  return meses.indexOf(d.mes) + 1;
})();
const anioExcel = d.anio;
var esMesActual = (mesExcel === mesActual) && (anioExcel === anioActual);

function formatUSD(val) {
  var num = Number(val) || 0;
  var rounded = Math.round(num * 100) / 100;
  var negativo = rounded < 0;
  var abs = Math.abs(rounded);
  var parts = abs.toFixed(2).split('.');
  var integerPart = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return (negativo ? '-' : '') + 'USD ' + integerPart + ',' + parts[1];
}

function formatNum(val) {
  var num = Number(val) || 0;
  var rounded = Math.round(num * 100) / 100;
  var parts = rounded.toFixed(2).split('.');
  var integerPart = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return integerPart + ',' + parts[1];
}

function esc(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function colorEstado(pct) {
  if (pct >= 100) return { color: '#f87171', bg: 'rgba(248,113,113,0.12)', label: 'EXCEDIDO' };
  if (pct >= 80)  return { color: '#facc15', bg: 'rgba(250,204,21,0.12)', label: 'ATENCIÓN' };
  return { color: '#4ade80', bg: 'rgba(74,222,128,0.12)', label: 'EN CONTROL' };
}

function barra(pct, color) {
  var p = Math.max(0, Math.min(100, pct));
  return '<div class="bar-track"><div class="bar-fill" style="width:' + p + '%; background:' + color + ';"></div></div>';
}

function nivelBadge(nivel) {
  if (nivel >= 40) return { color: '#f87171', bg: 'rgba(248,113,113,0.15)', label: 'ALTO' };
  if (nivel >= 15) return { color: '#facc15', bg: 'rgba(250,204,21,0.15)', label: 'MEDIO' };
  return { color: '#4ade80', bg: 'rgba(74,222,128,0.15)', label: 'BAJO' };
}

