    '  :root { --bg: #0f172a; --bg-card: #161f36; --border: #23304f; --text-primary: #e5e9f5; --text-secondary: #93a0c2; --accent: #38bdf8; }\n' +
    '  * { box-sizing: border-box; margin: 0; padding: 0; }\n' +
    '  body { background: var(--bg); color: var(--text-primary); font-family: \'Segoe UI\', -apple-system, BlinkMacSystemFont, Roboto, Arial, sans-serif; padding: 28px 16px 60px; }\n' +
    '  .container { max-width: 980px; margin: 0 auto; }\n' +
    '  header { text-align: center; margin-bottom: 28px; padding-bottom: 20px; border-bottom: 1px solid var(--border); }\n' +
    '  header h1 { font-size: 22px; font-weight: 700; }\n' +
    '  header p { color: var(--text-secondary); font-size: 13px; margin-top: 6px; }\n' +
    '  .author-badge { display: inline-block; margin-top: 8px; font-size: 11px; color: var(--accent); font-family: monospace; letter-spacing: 0.5px; }\n' +
    '  .summary-strip { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 12px; margin: 24px 0 40px; }\n' +
    '  .summary-box { background: var(--bg-card); border: 1px solid var(--border); border-radius: 12px; padding: 16px; }\n' +
    '  .summary-box .label { font-size: 12px; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.4px; }\n' +
    '  .summary-box .val { font-size: 20px; font-weight: 700; margin-top: 6px; }\n' +
    '  .summary-box .hint { font-size: 11px; color: var(--text-secondary); margin-top: 4px; }\n' +
    '  section { margin-bottom: 40px; }\n' +
    '  section > h2 { font-size: 17px; font-weight: 700; margin-bottom: 16px; }\n' +
    '  .panel { background: var(--bg-card); border: 1px solid var(--border); border-radius: 12px; padding: 18px; }\n' +
    '  .chart-box { width: 100%; overflow: hidden; }\n' +
    '  .chart-box.donut { display: flex; justify-content: center; }\n' +
    '  .legend { display: flex; flex-wrap: wrap; gap: 10px 16px; margin-top: 14px; justify-content: center; }\n' +
    '  .leg-item { display: inline-flex; align-items: center; font-size: 12px; color: var(--text-secondary); }\n' +
    '  .leg-dot { width: 11px; height: 11px; border-radius: 50%; margin-right: 6px; display: inline-block; }\n' +
    '  .dist-wrap { display: flex; flex-wrap: wrap; gap: 24px; align-items: center; justify-content: center; }\n' +
    '  .dist-legend { flex: 1; min-width: 240px; }\\n' +
