    '  table { border-collapse: collapse; width: 100%; min-width: 720px; font-size: 12.5px; }\n' +
    '  th, td { padding: 10px 12px; text-align: right; white-space: nowrap; border-bottom: 1px solid var(--border); }\n' +
    '  th { background: #101a30; color: var(--text-secondary); font-weight: 600; text-transform: uppercase; font-size: 11px; }\n' +
