    '<div class="summary-box"><div class="label">Promedio Semanal</div><div class="val">' + formatUSD(d.promedioSemanal) + '</div><div class="hint">Basado en ' + d.numSemanas + ' semanas</div></div>\n' +
    '<div class="summary-box"><div class="label">Días del Mes</div><div class="val">' + d.diasTotalesMes + '</div></div>\n' +
    '<div class="summary-box"><div class="label">Categorías con Gastos</div><div class="val">' + d.categoriasConGastos + '</div><div class="hint">de ' + d.totalCategorias + ' totales</div></div>\n' +
    '</div>\n' +
    '<section><h2>Evolución Semanal por Categoría</h2><div class="panel"><div class="chart-box">' + graficaEvolucion() + '</div><div class="legend">' + catsConGasto.map(function(c) { return '<span class="leg-item"><span class="leg-dot" style="background:' + c.color + ';\"></span>' + esc(c.nombre) + '</span>'; }).join('') + '</div></div></section>\n' +
    '<section><h2>Distribución de Gastos por Categoría</h2><div class="panel"><div class="dist-wrap"><div class="chart-box donut">' + graficaDistribucion() + '</div><div class="dist-legend">' + catsConGasto.slice().sort(function(a, b) { return b.total - a.total; }).map(function(c) { return '<div class="dist-item"><span class="leg-dot" style="background:' + c.color + ';\"></span><span class="dist-name">' + esc(c.emoji) + ' ' + esc(c.nombre) + '</span><span class="dist-val">' + formatUSD(c.total) + ' (' + c.pctTotal + '%)</span></div>'; }).join('') + '</div></div></div></section>\n' +
    '<section><h2>Detalle por Semana</h2>' + tablaDetalle() + '</section>\n' +
    '<section><h2>Resumen por Categoría</h2><div class="grid">' + resumenCategorias() + '</div></section>\n' +
    '<footer>\n' +
    '<p>Documento generado automáticamente · Royal Express C.A. · ' + esc(d.mes) + ' ' + d.anio + '</p>\n' +
    '<p style="font-size: 11px; margin-top: 4px; font-family: monospace;">SISTEMA AUTOMATIZADO ELABORADO Y PROGRAMADO POR: <strong>ING. VLADIMIR MARCANO</strong></p>\n' +
    '</footer>\n' +
