const ALIAS_MONTO = ['$', 'MONTO', 'MONTO ($)', 'IMPORTE', 'GASTO', 'VALOR', 'TOTAL', '__EMPTY_9', '__EMPTY_6', 'J'];
const ALIAS_FECHA = ['FECHA', 'FECHA GASTO', 'FECHA DE GASTO', 'DIA', 'DÍA', '__EMPTY_1', 'B'];

for (const item of inputItems) {
