if (executionType === 'alert_check') {
  const DIFERENCIA_MINIMA_USD = 50.00;
  const ahora = new Date();

  const registroAlertas = Object.assign({}, estadoPersistido.alertasGastos || {});

  const deptsExcedidosNotificar = [];
  const deptsProximosNotificar = [];

  DEPARTAMENTOS_CONFIG.forEach(function(dept) {
    const codigo = dept.codigo;
    const gastoPeriodo = Math.round((gastosPeriodoPorDept[codigo] || 0) * 100) / 100;
    const limiteSemanalAprox = dept.limiteMensual / 4;
    const porcentajePeriodo = limiteSemanalAprox > 0 ? (gastoPeriodo / limiteSemanalAprox) * 100 : 0;

    const storageKey = 'ALERT_' + anioExcel + '_' + mesExcel + '_S' + (semanaActualIdx + 1) + '_' + codigo;
    const previo = registroAlertas[storageKey] || null;

    if (porcentajePeriodo >= 90) {
      const estadoActual = porcentajePeriodo >= 100 ? 'ROJO' : 'AMARILLO';
      let debeAlertar = false;

      if (!previo) {
        // Primera vez que se detecta en zona de alerta
        debeAlertar = true;
      } else {
        const aumento = gastoPeriodo - (previo.monto || 0);
        const escaloARojo = (previo.estado === 'AMARILLO' && estadoActual === 'ROJO');

        // Solo se reenvia la alerta si:
        // 1. El gasto acumulado subio $50 USD o mas desde el ultimo aviso enviado
        // 2. O escalo de Amarillo (cerca del limite) a Rojo (excedido)
        // NO hay recordatorio automatico por tiempo: si el gasto no cambia,
        // no se repite la alerta aunque pasen varios dias.
        if (aumento >= DIFERENCIA_MINIMA_USD || escaloARojo) {
          debeAlertar = true;
        }
      }

      if (debeAlertar) {
        registroAlertas[storageKey] = {
          monto: gastoPeriodo,
          estado: estadoActual,
          timestamp: ahora.toISOString()
        };

        if (porcentajePeriodo >= 100) {
          const excedido = gastoPeriodo - limiteSemanalAprox;
          deptsExcedidosNotificar.push({
            nombre: dept.nombre,
            codigo: codigo,
            emoji: dept.emoji || '',
            gastoPeriodo: gastoPeriodo,
            limiteSemanalAprox: limiteSemanalAprox,
            porcentajePeriodo: porcentajePeriodo,
            excedido: excedido
          });
        } else {
          const disponible = limiteSemanalAprox - gastoPeriodo;
          deptsProximosNotificar.push({
            nombre: dept.nombre,
            codigo: codigo,
            emoji: dept.emoji || '',
            gastoPeriodo: gastoPeriodo,
            limiteSemanalAprox: limiteSemanalAprox,
            porcentajePeriodo: porcentajePeriodo,
            disponible: disponible
          });
        }
      }
    } else {
      // Si el gasto ya no está en zona de alerta (ej. nuevo período o ajuste), limpiamos
      if (previo) {
        delete registroAlertas[storageKey];
      }
    }
  });

  const totalAlertas = deptsExcedidosNotificar.length + deptsProximosNotificar.length;

  // Si no hay novedades reales que alertar -> SILENCIO TOTAL
  if (totalAlertas === 0) {
    return [{ json: {
      sendNotification: false,
      message: '',
      alertasCount: 0,
      persistClave: 'alertasGastos',
      persistValor: JSON.stringify(registroAlertas)
    } }];
  }

  let alertMsg = '🚨 <b>ROYAL EXPRESS C.A. - ALERTA DE GASTOS</b> 🚨\n\n📅 <b>Mes: ' + labelPeriodo + '</b>\n\n';
  if (deptsExcedidosNotificar.length > 0) {
    alertMsg += '🔴 <b>LIMITE EXCEDIDO</b>\nCategorias con consumo igual o mayor al limite establecido:\n\n';
    deptsExcedidosNotificar.forEach(function(d, idx) {
      let pctStr = d.porcentajePeriodo.toFixed(1).replace('.', ',') + '%';
      alertMsg += d.emoji + ' <b>' + d.nombre + '</b>\nEjecutado: ' + formatUSD(d.gastoPeriodo) + ' / Limite: ' + formatUSD(d.limiteSemanalAprox) + '\n% del limite: ' + pctStr + ' (Excedente: ' + formatUSD(d.excedido) + ')';
      if (idx < deptsExcedidosNotificar.length - 1) alertMsg += '\n\n───────────────────────\n\n';
    });
  }
  if (deptsProximosNotificar.length > 0) {
    if (deptsExcedidosNotificar.length > 0) alertMsg += '\n\n───────────────────────\n\n';
    alertMsg += '🟡 <b>PROXIMO A LIMITE</b>\nCategorias con 90% o mas de consumo (queda 10% o menos disponible):\n\n';
    deptsProximosNotificar.forEach(function(d, idx) {
      let pctStr = Math.round(d.porcentajePeriodo) + '%';
      alertMsg += d.emoji + ' <b>' + d.nombre + '</b>\nEjecutado: ' + formatUSD(d.gastoPeriodo) + ' / Limite: ' + formatUSD(d.limiteSemanalAprox) + '\n% del limite: ' + pctStr + ' (Disponible: ' + formatUSD(d.disponible) + ')';
      if (idx < deptsProximosNotificar.length - 1) alertMsg += '\n\n───────────────────────\n\n';
    });
  }
  alertMsg += '\n\n───────────────────────\n👨‍💻 <i>Sistema de información y automatización elaborado por: Ing. Vladimir Marcano</i>';
  return [{ json: {
    sendNotification: true,
    executionType: 'alert_check',
    message: alertMsg,
    gastoTotalGlobal: gastoTotalGlobalMes,
    alertasCount: totalAlertas,
    persistClave: 'alertasGastos',
    persistValor: JSON.stringify(registroAlertas)
  } }];
} else {
