      if (index < deptsResumen.length - 1) messageHtml += '───────────────────────\n\n';
    });
    messageHtml += '───────────────────────\n💼 <b>PRESUPUESTO MENSUAL GLOBAL</b>\n\nTotal Ejecutado (Mes) ' + formatUSD(gastoTotalGlobalMes);
  } else {
    messageHtml += '📊 <b>' + tituloCabecera + ' - ROYAL EXPRESS C.A.</b>\n📅 Mes: ' + labelPeriodo + '\n\n';
    deptsResumen.forEach(function(d, index) {
      messageHtml += d.emoji + '<b>' + d.departamento + '</b>\n• Semana en curso: ' + formatUSD(d.gastoPeriodo) + ' (Lim: ' + formatUSD(d.limiteSemanalAprox) + ')\n📉 Avance de la semana: [<code>' + d.barraPeriodo + '</code>] ' + Math.round(d.porcentajePeriodo) + '%\n\n• Acumulado al mes: ' + formatUSD(d.gastoMensual) + ' (Lim: ' + formatUSD(d.limiteMensual) + ')\n📈 Avance mensual: [<code>' + d.barraMensual + '</code>] ' + Math.round(d.porcentajeMensual) + '%\n';
      if (index < deptsResumen.length - 1) messageHtml += '───────────────────────\n';
    });
    const pctMensualGlobal = (gastoTotalGlobalMes / PRESUPUESTO_MENSUAL_GLOBAL) * 100;
    const barraMensualGlobal = generarBarraProgreso(pctMensualGlobal);
    const saldoDisponible = PRESUPUESTO_MENSUAL_GLOBAL - gastoTotalGlobalMes;
    messageHtml += '\n━━━━━━━━━━━━━━━━━━━━━━━\n💼 <b>PRESUPUESTO MENSUAL GLOBAL</b>\nPresupuesto total: ' + formatUSD(PRESUPUESTO_MENSUAL_GLOBAL) + '\n\nEjecutado hasta la fecha: ' + formatUSD(gastoTotalGlobalMes) + '\n📈 Avance Mensual: [<code>' + barraMensualGlobal + '</code>] ' + Math.round(pctMensualGlobal) + '%\n\n💰 Saldo disponible: ' + formatUSD(saldoDisponible);
  }
  messageHtml += '\n\n───────────────────────\n👨‍💻 <i>Sistema de información y automatización elaborado por: Ing. Vladimir Marcano</i>';
  return [{ json: { sendNotification: true, executionType: executionType, message: messageHtml, gastoTotalGlobal: gastoTotalGlobalMes, alertasCount: 0, deptsResumen: deptsResumen } }];
}

