if (!inputItems || inputItems.length === 0) {
  return [{
    json: {
      archivoNoEncontrado: true,
      mesNombre: 'ANUAL',
      message: '⚠️ <b>ROYAL EXPRESS C.A.</b>\n\nNo se encontraron archivos en la carpeta de OneDrive para generar el Informe Anual.\nVerifica que la carpeta \"2026\" exista y contenga los informes mensuales.'
    }
  }];
}

let listaArchivos = [];
const primerJson = inputItems[0].json;

if (primerJson && Array.isArray(primerJson.value)) {
  listaArchivos = primerJson.value;
} else {
  listaArchivos = inputItems.map(it => it.json).filter(Boolean);
}

if (listaArchivos.length === 0) {
  return [{
    json: {
      archivoNoEncontrado: true,
      mesNombre: 'ANUAL',
      message: '⚠️ <b>ROYAL EXPRESS C.A.</b>\n\nLa carpeta \"2026\" no devolvió archivos. Verifica los permisos de OneDrive o que existan los .xlsx mensuales.'
    }
  }];
}

const archivosEncontrados = [];
listaArchivos.forEach(archivo => {
  const nombre = (archivo && archivo.name) ? archivo.name.toUpperCase() : '';
  if (!nombre || !nombre.endsWith('.XLSX')) return;
  const mesDetectado = NOMBRES_MESES.find(m => nombre.includes(m));
  if (mesDetectado) {
    archivosEncontrados.push({ ...archivo, mesNombre: mesDetectado, archivoNoEncontrado: false });
  }
});

if (archivosEncontrados.length === 0) {
  const nombresDisponibles = listaArchivos.map(a => a && a.name).filter(Boolean).join(', ') || 'ninguno';
  return [{
    json: {
      archivoNoEncontrado: true,
      mesNombre: 'ANUAL',
      message: '⚠️ <b>ROYAL EXPRESS C.A.</b>\n\nNo se encontró ningún archivo .xlsx mensual válido en la carpeta \"2026\" para generar el Informe Anual.\n\nArchivos disponibles:\n' + nombresDisponibles
    }
  }];
}

return archivosEncontrados.map(a => ({ json: a }));

