function graficaEvolucionAnual() {
  var W = 900, H = 380;
  var padL = 64, padR = 20, padT = 20, padB = 44;
  var plotW = W - padL - padR;
  var plotH = H - padT - padB;
  var n = 12;

  var maxY = 0;
  catsConGasto.forEach(function(c) { c.porMes.forEach(function(v) { if (v > maxY) maxY = v; }); });
  if (maxY <= 0) maxY = 1;
  var step = Math.pow(10, Math.floor(Math.log10(maxY)));
  maxY = Math.ceil(maxY / step) * step;

  var xFor = function(i) { return padL + (n <= 1 ? plotW / 2 : (plotW * i) / (n - 1)); };
  var yFor = function(v) { return padT + plotH - (v / maxY) * plotH; };

  var grid = '';
  var lines = 4;
  for (var g = 0; g <= lines; g++) {
    var val = (maxY / lines) * g;
    var y = yFor(val);
    grid += '<line x1="' + padL + '" y1="' + y.toFixed(1) + '" x2="' + (W - padR) + '" y2="' + y.toFixed(1) + '" stroke="#23304f" stroke-width="1"/>';
    grid += '<text x="' + (padL - 8) + '" y="' + (y + 4).toFixed(1) + '" text-anchor="end" fill="#93a0c2" font-size="11">' + Math.round(val).toLocaleString('es-ES') + '</text>';
  }

  var xlabels = '';
  for (var i = 0; i < n; i++) {
    xlabels += '<text x="' + xFor(i).toFixed(1) + '" y="' + (H - padB + 22) + '" text-anchor="middle" fill="#93a0c2" font-size="11">' + MESES_ABREV[i] + '</text>';
  }

  var paths = '', dots = '';
  catsConGasto.forEach(function(c) {
    var pts = c.porMes.map(function(v, i) { return xFor(i).toFixed(1) + ',' + yFor(v).toFixed(1); });
    paths += '<polyline points="' + pts.join(' ') + '" fill="none" stroke="' + c.color + '" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>';
    c.porMes.forEach(function(v, i) {
      dots += '<circle cx="' + xFor(i).toFixed(1) + '" cy="' + yFor(v).toFixed(1) + '" r="3" fill="' + c.color + '"/>';
    });
  });

  return '<svg viewBox="0 0 ' + W + ' ' + H + '" width="100%" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg" role="img">' + grid + paths + dots + xlabels + '</svg>';
}

function graficaDistribucionAnual() {
  var size = 260, cx = size / 2, cy = size / 2, r = 100, rInner = 60;
  var total = catsConGasto.reduce(function(a, c) { return a + c.total; }, 0) || 1;

  var ang = -Math.PI / 2, segs = '';
  catsConGasto.forEach(function(c) {
    var frac = c.total / total;
    var a0 = ang, a1 = ang + frac * 2 * Math.PI;
    ang = a1;
    var large = (a1 - a0) > Math.PI ? 1 : 0;
    var x0 = cx + r * Math.cos(a0), y0 = cy + r * Math.sin(a0);
    var x1 = cx + r * Math.cos(a1), y1 = cy + r * Math.sin(a1);
    var xi1 = cx + rInner * Math.cos(a1), yi1 = cy + rInner * Math.sin(a1);
    var xi0 = cx + rInner * Math.cos(a0), yi0 = cy + rInner * Math.sin(a0);
    segs += '<path d="M ' + x0.toFixed(1) + ' ' + y0.toFixed(1) + ' A ' + r + ' ' + r + ' 0 ' + large + ' 1 ' + x1.toFixed(1) + ' ' + y1.toFixed(1) + ' L ' + xi1.toFixed(1) + ' ' + yi1.toFixed(1) + ' A ' + rInner + ' ' + rInner + ' 0 ' + large + ' 0 ' + xi0.toFixed(1) + ' ' + yi0.toFixed(1) + ' Z" fill="' + c.color + '"/>';
  });

  return '<svg viewBox="0 0 ' + size + ' ' + size + '" width="240" height="240" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg" role="img">' + segs + '<text x="' + cx + '" y="' + (cy - 6) + '" text-anchor="middle" fill="#93a0c2" font-size="12">Total año</text><text x="' + cx + '" y="' + (cy + 14) + '" text-anchor="middle" fill="#e5e9f5" font-size="14" font-weight="700">' + formatUSD(d.gastoTotalAnio).replace('USD ', '') + '</text></svg>';
}

