const filasResumen = obtenerFilas('Extraer RESUMEN Proveedores');

let proveedores = filasResumen.map(row => {
  const n = obtenerCampo(row, ['N°', 'N', 'NO', 'NUM', 'NUMERO']);
  const nombre = obtenerCampo(row, ['PROVEEDOR']);
  const responsable = obtenerCampo(row, ['RESPONSABLE']);
  const saldo = parseMonto(obtenerCampo(row, ['SALDO ADEUDADO', 'SALDO']));
  const observaciones = obtenerCampo(row, ['OBSERVACIONES']);
  return { n: n, nombre: nombre, responsable: responsable, saldo: saldo, observaciones: observaciones };
});

proveedores = proveedores.filter(p => {
  if (typeof p.n !== 'number') return false;
  if (!p.nombre) return false;
  if (normalizar(p.nombre).includes('TOTAL')) return false;
  return true;
});

// -----------------------------------------------------------
// 2) Mapa de hojas individuales por proveedor (para el último abono)
//    "keyword" = palabra clave única que debe aparecer en el
//    nombre del proveedor tal como está escrito en RESUMEN.
// -----------------------------------------------------------
const SHEETS_INFO = [
  { keyword: 'BACHAQUERO', nodeName: 'Extraer Hoja Retro Bachaquero', paymentCol: ['ABONO'], dateCol: ['FECHA'] },
  { keyword: 'FAMA', nodeName: 'Extraer Hoja Suministros Fama', paymentCol: ['HABER'], dateCol: ['FECHA'] },
  { keyword: 'CAUCHERA', nodeName: 'Extraer Hoja Cauchera Metra', paymentCol: ['ABONO'], dateCol: ['FECHA'] },
  { keyword: 'SOLUCIONES', nodeName: 'Extraer Hoja Soluciones Corp', paymentCol: ['ABONO'], dateCol: ['FECHA'] },
  { keyword: 'DIESEL', nodeName: 'Extraer Hoja Repuestos Diesel', paymentCol: ['ABONO'], dateCol: ['FECHA'] },
  { keyword: 'CORREA', nodeName: 'Extraer Hoja Mayor Correa', paymentCol: ['HABER'], dateCol: ['FECHA'] }
];

for (const p of proveedores) {
  p.ultimoAbonoFecha = null;
  p.ultimoAbonoMonto = 0;

  const nombreNorm = normalizar(p.nombre);
  const info = SHEETS_INFO.find(s => nombreNorm.includes(s.keyword));
  if (!info) continue;

  const filas = obtenerFilas(info.nodeName);
  let mejorFecha = null;
  let mejorMonto = 0;

  for (const fila of filas) {
    const montoAbono = parseMonto(obtenerCampo(fila, info.paymentCol));
    if (montoAbono > 0) {
      const fecha = parseFecha(obtenerCampo(fila, info.dateCol));
      if (fecha && (!mejorFecha || fecha.getTime() > mejorFecha.getTime())) {
        mejorFecha = fecha;
        mejorMonto = montoAbono;
      }
    }
  }

  p.ultimoAbonoFecha = mejorFecha ? mejorFecha.toISOString() : null;
  p.ultimoAbonoMonto = mejorMonto;
}

