// ---- 1. Ordenar y Obtener TODOS los Proveedores con Saldo ----
const ordenDesc = [...proveedores].sort((a, b) => (b.saldo || 0) - (a.saldo || 0));
const proveedoresConDeuda = ordenDesc.filter(p => (p.saldo || 0) > 0);

const maxSaldo = proveedoresConDeuda.length ? (proveedoresConDeuda[0].saldo || 1) : 1;
const coloresBarra = [
  { bg: 'linear-gradient(90deg, #ef4444, #f87171)', txt: '#fca5a5' }, // 1. Rojo (Mayor deuda)
  { bg: 'linear-gradient(90deg, #f59e0b, #fbbf24)', txt: '#fde047' }, // 2. Ámbar
  { bg: 'linear-gradient(90deg, #3b82f6, #60a5fa)', txt: '#93c5fd' }, // 3. Azul
  { bg: 'linear-gradient(90deg, #8b5cf6, #a78bfa)', txt: '#c4b5fd' }, // 4. Púrpura
  { bg: 'linear-gradient(90deg, #06b6d4, #22d3ee)', txt: '#67e8f9' }, // 5. Cyan
  { bg: 'linear-gradient(90deg, #10b981, #34d399)', txt: '#86efac' }  // 6. Verde
];

let barrasHtml = '';
proveedoresConDeuda.forEach(function (p, idx) {
  const pct = maxSaldo > 0 ? Math.max(6, Math.round(((p.saldo || 0) / maxSaldo) * 100)) : 6;
  const paleta = coloresBarra[idx % coloresBarra.length];
  barrasHtml +=
    '<div class="bar-item">' +
      '<div class="bar-name" title="' + esc(p.nombre) + '">' + esc(p.nombre) + '</div>' +
      '<div class="bar-track">' +
        '<div class="bar-fill" style="width: ' + pct + '%; background: ' + paleta.bg + ';"></div>' +
      '</div>' +
      '<div class="bar-amount" style="color: ' + paleta.txt + ';">' + fmt(p.saldo) + '</div>' +
    '</div>';
});

// ---- 2. Tabla de Detalle Completa ----
const rankPorNombre = {};
ordenDesc.forEach((p, idx) => { rankPorNombre[p.nombre] = idx; });

let filasTabla = '';
proveedores.forEach(function (p) {
  const rank = rankPorNombre[p.nombre];
  const colorClase = rank === 0 ? 'text-red' : (rank === 1 ? 'text-amber' : 'text-white');
  const abonoMonto = p.ultimoAbonoMonto ? fmt(p.ultimoAbonoMonto) : '-';
  const abonoFecha = p.ultimoAbonoFecha ? fmtFecha(p.ultimoAbonoFecha) : '-';
  filasTabla +=
    '<tr>' +
    '<td class="font-mono text-slate">' + esc(p.n) + '</td>' +
    '<td class="font-bold text-white uppercase">' + esc(p.nombre) + '</td>' +
    '<td class="text-slate-light">' + esc(p.responsable || '-') + '</td>' +
    '<td class="text-right font-bold text-green font-mono">' + abonoMonto + '</td>' +
    '<td class="text-right text-slate font-mono">' + abonoFecha + '</td>' +
    '<td class="text-right font-bold ' + colorClase + ' font-mono" style="font-size: 15px;">' + fmt(p.saldo) + '</td>' +
    '</tr>';
});

