// Reconstruye el objeto de estado persistente (anti-spam de alertas de
// gastos) desde la Data Table. Corre en paralelo a la lectura del Excel:
// asi "Procesar y Evaluar Gastos" lo consulta por nombre
// ($('Parsear Estado Gastos')) sin que este item de estado se mezcle
// con las filas de gastos que vienen del Excel.
var rows = $input.all();
var estado = {};
rows.forEach(function (it) {
  var k = it.json && it.json.clave;
  var v = it.json && it.json.valor;
  if (!k) return;
  try { estado[k] = v ? JSON.parse(v) : {}; } catch (e) { estado[k] = {}; }
});
return [{ json: { estado: estado } }];
